"""Caesar shift of ASCII letters, such as ROT13: "Hello" -> "Uryyb" with n=13."""
import string

_LOWER = string.ascii_lowercase
_UPPER = string.ascii_uppercase


def rot(text, n):
    """Shift each ASCII letter in text by n places, wrapping around and keeping case. Other characters are unchanged. n must be an int."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError(f"n must be an int: {n!r}")
    shift = n % 26
    table = {}
    for alphabet in (_LOWER, _UPPER):
        for i, ch in enumerate(alphabet):
            table[ord(ch)] = alphabet[(i + shift) % 26]
    return text.translate(table)
