import contextlib
import io
import unittest

from textkit.cli import main
from textkit.topwords import top_words


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class TopWordsTest(unittest.TestCase):
    def test_counts_and_sorts_by_count(self):
        self.assertEqual(top_words("b a b c a b", 2), [("b", 3), ("a", 2)])

    def test_ties_are_alphabetical(self):
        self.assertEqual(top_words("zeta alpha mid", 3), [("alpha", 1), ("mid", 1), ("zeta", 1)])

    def test_case_insensitive(self):
        self.assertEqual(top_words("The the THE cat", 1), [("the", 3)])

    def test_splits_on_non_letters(self):
        # "don't" is "don" and "t"; digits and punctuation also separate words.
        self.assertEqual(top_words("don't stop2 stop-me", 10),
                         [("stop", 2), ("don", 1), ("me", 1), ("t", 1)])

    def test_non_ascii_letters_are_separators(self):
        self.assertEqual(top_words("café café", 5), [("caf", 2)])

    def test_fewer_distinct_words_than_k(self):
        self.assertEqual(top_words("only", 5), [("only", 1)])

    def test_empty_text(self):
        self.assertEqual(top_words("", 3), [])
        self.assertEqual(top_words("123 !!!", 3), [])

    def test_k_below_one_raises(self):
        for bad in [0, -1]:
            with self.subTest(k=bad):
                with self.assertRaises(ValueError):
                    top_words("a b", bad)


class TopCommandTest(unittest.TestCase):
    def test_prints_word_and_count_lines(self):
        self.assertEqual(run("top", "b a b c a b", "--k", "2"), (0, "b 3\na 2\n", ""))

    def test_default_k_is_three(self):
        self.assertEqual(run("top", "d c c b b b a a a a"), (0, "a 4\nb 3\nc 2\n", ""))

    def test_k_zero_is_error(self):
        code, out, err = run("top", "x", "--k", "0")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error:"))

    def test_json_output(self):
        code, out, _ = run("--json", "top", "b a b", "--k", "1")
        self.assertEqual(code, 0)
        self.assertIn('"output": ["b 2"]', out)

    def test_listed_in_commands(self):
        code, out, _ = run("commands")
        self.assertEqual(code, 0)
        self.assertIn("top", out.split())


if __name__ == "__main__":
    unittest.main()

